/**
 * The two questions the on-device model answers, as prompts, plus the arithmetic that turns the model's option logits
 * into probabilities.
 *
 * Source of truth: `ml/prompt.py`. These must reproduce its strings byte for byte, because the model was trained on
 * exactly that text; `test/classifier-prompt.test.ts` checks every string against vectors generated by the Python side
 * (`ml/golden_prompts.py`). That includes Python's own idea of whitespace and character counting, which differ from
 * JavaScript's in a few places.
 */
import { TOS_CATEGORIES } from './labels.ts';

export const LETTERS = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I'] as const;
export const LETTERS_PROMPT_VERSION = 'letters-v1';
export const PII_PROMPT_VERSION = 'pii-v1';
export const PII_MAX_CHARS = 1_200;

/** What Python's `str.isspace()` / `str.split()` treat as whitespace (JavaScript's `\s` also matches U+FEFF and misses \x1c-\x1f, \x85). */
const PY_WS = '\\t\\n\\v\\f\\r\\x1c-\\x1f \\x85\\xa0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000';
const PY_WS_RUN = new RegExp(`[${PY_WS}]+`, 'u');
const PY_STRIP = new RegExp(`^[${PY_WS}]+|[${PY_WS}]+$`, 'gu');

const pyStrip = (text: string) => text.replace(PY_STRIP, '');
const pyCollapse = (text: string) => text.split(PY_WS_RUN).filter(Boolean).join(' ');
/** `text[:n]` by Unicode code points, as Python slices, so an emoji at the cut is never split in half. */
const firstChars = (text: string, n: number) => Array.from(text).slice(0, n).join('');

const OPTIONS = TOS_CATEGORIES.map((name, i) => `${LETTERS[i]}) ${name.replaceAll('_', ' ')}`).join('\n');

/** Question 1: which kind of clause is this passage? Answered with a letter A–I (`TOS_CATEGORIES` order). */
export function letterPrompt(passage: string): string {
  return `Classify this terms-of-service passage.\n${OPTIONS}\n\nPassage: ${pyStrip(passage)}\nAnswer:`;
}

/**
 * Question 2: does this page show private information about the person using it? A = personal, B = public.
 * Only host and path go in, decoded the way a person reads them; the query string and fragment never do.
 */
export function piiPrompt(url: string, text: string): string {
  const u = new URL(url);
  const path = percentDecode(u.pathname);
  const page = firstChars(pyCollapse(text), PII_MAX_CHARS);
  return (
    'Decide whether this web page shows private information about the person using it ' +
    '(their account, orders, messages, health, finances, contact or ID details) or is a public page.\n' +
    `A) personal\nB) public\n\nPage address: ${u.host}${path}\nPage text: ${page}\nAnswer:`
  );
}

/** Python's `urllib.parse.unquote`: decodes each run of %XX escapes as UTF-8, leaving malformed ones alone (and bad bytes as U+FFFD). */
function percentDecode(path: string): string {
  return path.replace(/(?:%[0-9A-Fa-f]{2})+/g, (run) => {
    const bytes = Uint8Array.from(run.match(/%([0-9A-Fa-f]{2})/g)!, (h) => parseInt(h.slice(1), 16));
    return new TextDecoder('utf-8').decode(bytes);
  });
}

/** Softmax of `logits / temperature`. The temperature was fitted on held-out data and ships with each model. */
export function probabilities(logits: ArrayLike<number>, temperature = 1): number[] {
  const z = Array.from(logits, (x) => x / temperature);
  const max = Math.max(...z);
  const e = z.map((x) => Math.exp(x - max));
  const sum = e.reduce((a, b) => a + b, 0);
  return e.map((x) => x / sum);
}
